"use client";
import { FormEvent,useCallback,useEffect,useState } from "react";
import "./reference-control.css";

type Model={id:string;label:string;provider:string;base_url:string;model_id:string;api_key_env:string;is_active:number;credential_configured:boolean;config:{temperature?:number;max_tokens?:number}};
type RunContext={mode?:string;selectedSkill?:string;availableSkills?:Array<{name:string;description?:string}>;publishedMemories?:Array<Record<string,unknown>>;publishedProfile?:Array<Record<string,unknown>>;toolSteps?:Array<{round?:number;call?:{name?:string;input?:Record<string,unknown>};result?:unknown;error?:string}>;runtimePolicy?:Record<string,unknown>;instruction?:string;[key:string]:unknown};
type Run={id:string;task_id?:string;source:string;status:string;provider?:string;model_id?:string;input_text:string;context_json:string;context?:RunContext;output_text?:string;error?:string;input_chars:number;output_chars:number;latency_ms?:number;created_at:string;trace?:Array<{event?:string}>;tools?:ToolRun[]};
type SkillTone="blue"|"purple"|"cyan"|"orange"|"pink"|"gray";
type SkillTag={id?:string|null;name:string;tone:SkillTone};
type Capability={id:string;kind:"skill"|"plugin";name:string;description:string;version:string;enabled:number;source:string;last_run_at?:string;config?:{status?:string;compatibility?:string;pinnedCommit?:string;tag?:SkillTag}};
type SkillVersion={id:string;version:string;status:string;content:string;change_summary:string;created_by:string;created_at:string;evaluation?:{score?:number;gate?:string;checks?:Array<{name:string;pass:boolean}>}};
type Skill=Capability&{versions:SkillVersion[];evolutions:Array<{id:string;status:string;diagnosis:string;created_at:string;candidate_version_id?:string}>;usage:{calls:number;failures:number;avg_latency?:number}};
type MemoryEntry={id:string;content:string;memory_type:string;subject_type?:"workspace"|"project"|"person";subject_id?:string;status:string;confidence:number;importance:number;created_by:string;created_at:string;updated_at:string};
type MemoryScope={id:string|null;type:"workspace"|"project"|"person";name:string;definition:string;summary:string;published:number;candidates:number;entries:MemoryEntry[]};
type MemoryReview={id:string;status:string;period_start:string;period_end:string;source_count:number;summary?:string;error?:string;created_at:string};
type ToolRun={id:string;agent_run_id?:string;tool_name:string;agent_role:string;status:string;permission:string;plugin_name?:string;latency_ms?:number;error?:string;created_at:string;input?:Record<string,unknown>;output?:unknown};
type ProfileFact={id:string;category:string;key:string;value:string;status:string;confidence:number;evidence_count:number;created_by:string;created_at:string};
type SystemPromptVersion={id:string;prompt_key:string;version:number;status:"published"|"draft"|"archived"|"fallback";content:string;change_summary:string;created_by:string;created_at:string;updated_at:string};
type SystemPromptControl={key:string;label:string;description:string;active:SystemPromptVersion;versions:SystemPromptVersion[]};
type DelegationTask={id:string;role:string;status:string;latency_ms?:number;error?:string;dependencies?:string[]};
type DelegationRun={id:string;skill_name:string;status:string;max_concurrency:number;created_at:string;error?:string;tasks:DelegationTask[]};
type ChannelRuntime={driver:string;status:string;ready?:boolean;lastReadyAt?:string|null;lastEventAt?:string|null;lastReplyAt?:string|null;lastError?:string|null;eventsReceived?:number;repliesSent?:number;restarts?:number};
type GroupSync={chat_id:string;enabled:number;output_doc_url?:string;last_message_at?:string;last_history_sync_at?:string;last_history_sync_count?:number;last_history_sync_error?:string;last_summarized_at?:string;last_written_at?:string;last_summary?:string;last_error?:string;pending_messages:number};
type ScheduledTask={id:string;name:string;prompt:string;skill_name:string;schedule:{type:string;time?:string;weekdays?:number[];runAt?:string;timezone?:string};scope_type:string;scope_id:string;creator_name?:string;delivery_type:string;status:string;next_run_at?:string;last_run_at?:string;last_output?:string;last_error?:string};
type DocumentAccess={identity:string;status:string;available?:boolean;verified?:boolean;userName?:string|null;message?:string|null;hint?:string|null};
type WebAccess={pluginEnabled:boolean;search:boolean;searchConfigured:boolean;provider:string|null;fetch:boolean;fetchConfigured:boolean;tools:Array<{name:string;available:boolean}>};
type SessionInfo={id:string;channel:string;peer_id:string;external_chat_id?:string;preview?:string;message_count:number;updated_at:string;snapshot?:{user_md:string;memory_md:string;snapshot_period:string;created_at:string;updated_at:string}|null};
type KnowledgeItem={id:string;project_id:string;project_name:string;knowledge_type:string;title:string;content:string;source_type:string;source_url?:string;chat_id?:string;people?:string[];occurred_at:string};
type KnowledgeProject={id:string;name:string;health:string;progress:number;itemCount:number;documentCount:number;chatCount:number;people:string[]};
type ControlView="overview"|"models"|"prompts"|"skills"|"plugins"|"memory"|"knowledge"|"feishu"|"schedules"|"delegation"|"tools";
type ControlData={activeModel:Model|null;models:Model[];systemPrompt:SystemPromptControl;skillTags:SkillTag[];runs:Run[];capabilities:Capability[];skills:Skill[];plugins:Capability[];toolRuns:ToolRun[];delegations:DelegationRun[];groupSyncs:GroupSync[];scheduledTasks:ScheduledTask[];sessions:SessionInfo[];knowledge:{projects:KnowledgeProject[];items:KnowledgeItem[];totals:{projects:number;items:number}};documentAccess?:DocumentAccess;webAccess?:WebAccess;memory:{entries:MemoryEntry[];reviews:MemoryReview[];totals:{total?:number;published?:number;candidates?:number};scopes?:{workspace:MemoryScope[];projects:MemoryScope[];people:MemoryScope[]}};profile:{entries:ProfileFact[];published:ProfileFact[];totals:{total?:number;published?:number;candidates?:number}};curator?:{name:string;status:string;mode:string;publish_policy:string};memoryCurator?:{name:string;status:string;schedule:string;mode:string;publish_policy:string};architecture?:Record<string,string>;channelRuntime?:ChannelRuntime;totals:{runs:number;completed:number;avg_latency?:number;input_chars?:number;output_chars?:number}};
const emptyPrompt:SystemPromptControl={key:"personal-assistant",label:"个人生活工作管理助手",description:"",active:{id:"",prompt_key:"personal-assistant",version:0,status:"fallback",content:"",change_summary:"",created_by:"system",created_at:"",updated_at:""},versions:[]};
const empty:ControlData={activeModel:null,models:[],systemPrompt:emptyPrompt,skillTags:[],runs:[],capabilities:[],skills:[],plugins:[],toolRuns:[],delegations:[],groupSyncs:[],scheduledTasks:[],sessions:[],knowledge:{projects:[],items:[],totals:{projects:0,items:0}},memory:{entries:[],reviews:[],totals:{}},profile:{entries:[],published:[],totals:{}},totals:{runs:0,completed:0}};
const defaultSkillTags:SkillTag[]=[{name:"项目协作",tone:"blue"},{name:"汇报表达",tone:"purple"},{name:"知识检索",tone:"cyan"},{name:"自动化执行",tone:"orange"},{name:"记忆学习",tone:"pink"},{name:"通用助理",tone:"gray"}];
let runtimeSkillTags:SkillTag[]=defaultSkillTags;

async function responseJson(response:Response){
  const text=await response.text();
  if(!text)return {};
  try{return JSON.parse(text)}
  catch{return {error:response.ok?"服务端返回了无法识别的数据":text.slice(0,500)}}
}

export default function ControlPage(){
  const[data,setData]=useState(empty),[loading,setLoading]=useState(true),[error,setError]=useState(""),[selected,setSelected]=useState<Run|null>(null),[selectedSkillId,setSelectedSkillId]=useState<string|null>(null),[showAdd,setShowAdd]=useState(false),[showAddSkill,setShowAddSkill]=useState(false),[showAddSkillTag,setShowAddSkillTag]=useState(false),[discovered,setDiscovered]=useState<Array<{id:string;ownedBy:string}>>([]),[busyAction,setBusyAction]=useState(""),[documentAccess,setDocumentAccess]=useState<DocumentAccess|null>(null),[memoryScopeView,setMemoryScopeView]=useState<"projects"|"people"|"workspace">("projects"),[openMemoryScope,setOpenMemoryScope]=useState<string|null>(null),[skillShelfView,setSkillShelfView]=useState<"published"|"drafts">("published"),[skillTagView,setSkillTagView]=useState("all"),[view,setView]=useState<ControlView>("overview");
  const refresh=useCallback(async(silent=false)=>{try{const r=await fetch("/api/control",{cache:"no-store"});const j=await responseJson(r) as ControlData&{error?:string};if(!r.ok)throw new Error(j.error||`控制中台请求失败（${r.status}）`);runtimeSkillTags=j.skillTags?.length?j.skillTags:defaultSkillTags;setData(j);setError("")}catch(e){if(!silent)setError(e instanceof Error?e.message:"控制中台不可用")}finally{setLoading(false)}},[]);
  useEffect(()=>{void refresh();const timer=window.setInterval(()=>{if(document.visibilityState==="visible")void refresh(true)},5000);return()=>clearInterval(timer)},[refresh]);
  async function action(body:Record<string,unknown>){const r=await fetch("/api/control",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(body)});const j=await responseJson(r);if(!r.ok)throw new Error(j.error||`控制中台请求失败（${r.status}）`);await refresh(true);return j}
  async function guarded(key:string,body:Record<string,unknown>){try{setBusyAction(key);setError("");return await action(body)}catch(e){setError(e instanceof Error?e.message:"操作失败");throw e}finally{setBusyAction("")}}
  async function discover(){try{const j=await action({action:"discover_models"});setDiscovered(j.models||[])}catch(e){setError(e instanceof Error?e.message:"无法读取 API 模型列表")}}
  const success=data.totals.runs?Math.round((Number(data.totals.completed||0)/Number(data.totals.runs))*100):0;
  const viewTitle:Record<ControlView,string>={overview:"运行总览",models:"模型与日志",prompts:"系统提示词",skills:"Skill 管理",plugins:"插件管理",memory:"Memory 管理",knowledge:"项目知识库",feishu:"飞书与文档",schedules:"定时任务",delegation:"子 Agent",tools:"工具审计"};
  return <main className="control-shell">
    <aside className="control-rail"><div className="rail-brand"><a href="/" className="control-logo"><i/></a><span><b>Pulse Agent</b><small>管理控制台</small></span></div><a className="back-workspace" href="/">项目与周报 <span>↗</span></a><nav>{([ ["overview","运行总览"],["models","模型与日志"],["prompts","系统提示词"],["skills","Skill 管理"],["plugins","插件管理"],["memory","Memory 管理"],["knowledge","项目知识库"],["feishu","飞书与文档"],["schedules","定时任务"],["delegation","子 Agent"],["tools","工具审计"]] as Array<[ControlView,string]>).map(([id,label])=><button key={id} className={view===id?"active":""} onClick={()=>setView(id)}><i/>{label}</button>)}</nav><small>PULSE · CONTROL</small></aside>
    <section className="control-main">
      <header className="control-header"><div><p>AGENT CONTROL</p><h1>{viewTitle[view]}</h1></div><div className="live-state"><i/>实时监控 · 5 秒刷新</div></header>
      {error&&<div className="control-error">{error}</div>}
      {(view==="overview"||view==="models")&&<section className="control-stats">
        <div><small>当前请求模型</small><strong>{data.activeModel?.model_id||"未配置"}</strong><span>{data.activeModel?.provider||"—"}</span></div>
        <div><small>模型调用</small><strong>{data.totals.runs||0}</strong><span>累计 Run</span></div>
        <div><small>成功率</small><strong>{success}%</strong><span>{data.totals.completed||0} 次完成</span></div>
        <div><small>平均耗时</small><strong>{formatMs(data.totals.avg_latency)}</strong><span>{formatChars(Number(data.totals.input_chars||0))} 输入字符</span></div>
      </section>}

      {view==="models"&&<section className="control-grid">
        <section className="ops-card run-card"><header><div><p>MODEL RUNS</p><h2>模型输入与输出日志</h2></div><span>{data.runs.length} 条</span></header>{loading?<div className="control-empty">正在读取运行记录…</div>:data.runs.length?<div className="run-table"><div className="run-head"><span>时间 / 来源</span><span>模型</span><span>输入 / 输出</span><span>耗时</span><span>状态</span></div>{data.runs.map(run=><button key={run.id} onClick={()=>setSelected(run)}><span><b>{time(run.created_at)}</b><small>{run.source}</small></span><span><b>{run.model_id||"fallback"}</b><small>{run.provider||"local"}</small></span><span><b>{formatChars(run.input_chars)} → {formatChars(run.output_chars)}</b><small>{run.input_text.slice(0,42)||"无输入"}</small></span><span>{formatMs(run.latency_ms)}</span><span className={`run-status ${run.status}`}>{status(run.status)}</span></button>)}</div>:<div className="control-empty">还没有模型调用。给 Bot 发送问题或文档后，这里会记录完整链路。</div>}</section>

        <aside className="ops-card model-card"><header><div><p>MODEL ROUTING</p><h2>请求模型</h2></div><button onClick={()=>setShowAdd(true)}>＋ 添加</button></header>{data.models.map(model=><div className={model.is_active?"model-row active":"model-row"} key={model.id}><div><i>{model.is_active?"●":"○"}</i><span><b>{model.label}</b><small>{model.model_id}</small></span></div><p>{model.credential_configured?"凭证已连接":"缺少凭证"} · {model.base_url.replace(/^https?:\/\//,"")}</p>{model.is_active?<em>当前模型</em>:<button onClick={()=>action({action:"activate_model",id:model.id}).catch(e=>setError(e.message))}>切换</button>}</div>)}<button className="discover" onClick={discover}>从当前 API 读取可用模型</button>{discovered.length>0&&<div className="discovered">{discovered.map(item=><span key={item.id}>{item.id}</span>)}</div>}<div className="model-note">密钥只读取环境变量，不会进入页面、数据库或日志。模型切换从下一次请求开始生效。</div></aside>
      </section>}

      {view==="prompts"&&<SystemPromptStudio prompt={data.systemPrompt||emptyPrompt} busy={busyAction} act={guarded}/>}

      {view==="skills"&&<section className="library-layout single-library">
        <section className="ops-card skill-library">
          <header><div><p>SKILL LIBRARY</p><h2>Skill 能力研发中台</h2></div><div className="skill-header-actions"><div className="curator-state"><i/><span><b>Skill Curator</b> 人工发布模式</span></div><button className="new-skill-tag" onClick={()=>setShowAddSkillTag(true)}>＋ 新建用途</button><button className="new-skill" onClick={()=>setShowAddSkill(true)}>＋ 新建 Skill</button></div></header>
          <p className="library-intro">代码同步、人工创建和 Curator 生成的能力统一进入草稿箱；只有审核发布后的版本才会进入 Agent 的生产 Skill 目录。发布动作会自动完成规则评测并启用通过版本。</p>
          <nav className="skill-shelf-tabs"><button className={skillShelfView==="published"?"active":""} onClick={()=>setSkillShelfView("published")}>已发布 <b>{data.skills.filter(skill=>skill.versions.some(version=>version.status==="published")).length}</b></button><button className={skillShelfView==="drafts"?"active":""} onClick={()=>setSkillShelfView("drafts")}>草稿箱 <b>{data.skills.reduce((total,skill)=>total+skill.versions.filter(version=>version.status==="draft"||version.status==="candidate").length,0)}</b></button></nav>
          {skillShelfView==="published"?<SkillLibraryTable skills={data.skills.filter(skill=>skill.versions.some(version=>version.status==="published"))} tag={skillTagView} setTag={setSkillTagView} manage={setSelectedSkillId}/>:<div className="draft-skill-list">{data.skills.flatMap(skill=>skill.versions.filter(version=>version.status==="draft"||version.status==="candidate").map(version=>({skill,version}))).map(({skill,version})=>{const tag=skillTagMeta(skill);return <article key={version.id}><div className="draft-skill-main"><span className={`skill-use-tag ${tag.tone}`}>{tag.name}</span><span className={`version-status ${version.status}`}>{version.status==="candidate"?"候选":"草稿"}</span><div><h3>{skill.name} <small>v{version.version}</small></h3><p>{version.change_summary||skill.description}</p><span>{version.created_by==="code-sync"?"代码同步自动导入":version.created_by} · {time(version.created_at)}</span></div></div><div className="draft-skill-actions"><span>评测 {version.evaluation?.score!=null?`${version.evaluation.score}/100`:"将在发布时自动运行"}</span><button onClick={()=>setSelectedSkillId(skill.id)}>预览编辑</button><button className="primary" disabled={busyAction===version.id} onClick={()=>{if(window.confirm(`发布 Skill「${skill.name}」v${version.version}？发布后将进入 Agent 生产目录。`))guarded(version.id,{action:"publish_skill_draft",versionId:version.id}).catch(()=>{})}}>{busyAction===version.id?"发布中…":"审核并发布"}</button></div></article>})}{!data.skills.some(skill=>skill.versions.some(version=>version.status==="draft"||version.status==="candidate"))&&<div className="control-empty">草稿箱为空。代码同步的新 Skill 会在服务重启后自动出现在这里，无需复制粘贴。</div>}</div>}
        </section>
      </section>}

      {view==="plugins"&&<section className="ops-card plugin-library standalone-library"><header><div><p>PLUGIN LIBRARY</p><h2>插件、连接与 Tool</h2></div><span>{data.plugins.filter(plugin=>plugin.enabled).length} / {data.plugins.length}</span></header><p className="library-intro">插件决定 Agent 实际拥有的外部能力。停用插件后，它所属的 Tool 会从下一轮 Agent 工具目录中移除；这里展示的是运行时真实配置与调用记录，不是静态占位状态。</p><div className="plugin-list">{data.plugins.map(plugin=>{const isWeb=plugin.name==="web-access",runs=data.toolRuns.filter(run=>run.plugin_name===plugin.name),failed=runs.filter(run=>run.status==="failed").length;return <article key={plugin.id} className={isWeb?"tool-plugin-card":""}><div><span className="plugin-mark">{plugin.name.slice(0,2).toUpperCase()}</span><span><b>{plugin.name}</b><small>{plugin.description}</small></span><button aria-label={`${plugin.enabled?"停用":"启用"} ${plugin.name}`} className={plugin.enabled?"toggle on":"toggle"} onClick={()=>guarded(plugin.id,{action:"toggle_capability",id:plugin.id,enabled:!plugin.enabled}).catch(()=>{})}><i/></button></div>{isWeb&&<div className="plugin-tool-status"><div><small>搜索 Provider</small><b>{data.webAccess?.provider||"未配置"}</b><em className={data.webAccess?.search?"ready":"offline"}>{data.webAccess?.search?"可用":data.webAccess?.searchConfigured?"插件已停用":"未配置"}</em></div><div className="plugin-tools">{(data.webAccess?.tools||[{name:"web_search",available:false},{name:"web_fetch",available:false}]).map(tool=><span key={tool.name} className={tool.available?"ready":""}><i/>{tool.name}</span>)}</div><p>最近 {runs.length} 次调用 · {failed} 次失败。搜索结果与网页正文均作为不可信证据进入 Agent Loop，并保留 Tool 审计。</p></div>}<footer><span>v{plugin.version}</span><span>{plugin.source}</span><em>{plugin.last_run_at?`最近运行 ${time(plugin.last_run_at)}`:"尚未运行"}</em></footer></article>})}</div></section>}

      {view==="overview"&&<section className="architecture-strip ops-card"><header><div><p>AGENT ARCHITECTURE</p><h2>系统组件状态</h2></div><span>{data.channelRuntime?.ready?"飞书 CLI 在线":data.channelRuntime?.status==="reconnecting"?"飞书 CLI 重连中":"飞书 CLI 未就绪"}</span></header><div>{Object.entries(data.architecture||{}).map(([key,value])=><article key={key}><small>{architectureLabel(key)}</small><b>{value}</b></article>)}<article><small>CLI 消息链路</small><b>{data.channelRuntime?.status||"unknown"}</b></article><article><small>接收 / 回复</small><b>{data.channelRuntime?.eventsReceived||0} / {data.channelRuntime?.repliesSent||0}</b></article></div>{data.channelRuntime?.lastError&&<p className="channel-error">{data.channelRuntime.lastError}</p>}</section>}

      {view==="feishu"&&<section className="ops-card group-sync-card"><header><div><p>FEISHU KNOWLEDGE PIPELINE</p><h2>群聊历史、沉淀与文档同步</h2></div><div><button disabled={busyAction==="doc-access"} onClick={async()=>{const value=await guarded("doc-access",{action:"check_document_access"}) as DocumentAccess;setDocumentAccess(value)}}>{busyAction==="doc-access"?"检查中…":"检查用户授权"}</button><button className="primary" disabled={busyAction==="group-sync"} onClick={()=>guarded("group-sync",{action:"run_group_sync"}).catch(()=>{})}>{busyAction==="group-sync"?"同步中…":"补采历史并同步"}</button></div></header><div className="access-strip"><span className={documentAccess?.verified?"access-dot ok":"access-dot"}/><div><b>{documentAccess?.verified?`用户身份已连接 · ${documentAccess.userName||"飞书用户"}`:"历史消息优先使用用户身份"}</b><p>{documentAccess?.message||"Bot 事件只接收新增消息；历史记录优先用已授权用户身份补采，权限不足时回退到群内 Bot 身份，并按群隔离写入本地证据库。"}</p></div></div>{(data.groupSyncs||[]).length?<div className="group-sync-list">{(data.groupSyncs||[]).map(sync=><article key={sync.chat_id}><div><i>群</i><span><b>{sync.chat_id}</b><small>{sync.pending_messages} 条待整理 · {sync.last_history_sync_at?`最近补采 ${time(sync.last_history_sync_at)}，读取 ${sync.last_history_sync_count||0} 条`:"尚未补采历史"}</small></span></div><p>{sync.last_history_sync_error||sync.last_error||sync.last_summary||"新消息持续静默沉淀；需要总结、查询发言或执行定时任务时会先补采历史。"}</p><footer><span>{sync.last_history_sync_error?"历史读取异常":sync.last_error?"文档同步异常":sync.output_doc_url?"历史与文档已连接":"历史读取已就绪"}</span>{sync.output_doc_url&&<a href={sync.output_doc_url} target="_blank" rel="noreferrer">打开飞书文档 ↗</a>}</footer></article>)}</div>:<div className="control-empty">Bot 加入群后会持续接收新消息；首次总结、查询发言或定时任务执行前，会补采该群最近的历史消息。</div>}</section>}

      {view==="schedules"&&<section className="ops-card schedule-card"><header><div><p>AGENT SCHEDULER</p><h2>定时任务与主动推送</h2></div><span>{(data.scheduledTasks||[]).filter(task=>task.status==="active").length} 个运行中</span></header><p className="library-intro">在任意已启用群中 @Alex 直接创建，例如：“每天晚上 9 点私聊我当天项目进度总结”或“每周五 18:00 在本群发送风险回顾”。任务按群和创建人隔离，到点后重新进入 Agent Loop，并保留模型、工具和投递日志。</p>{(data.scheduledTasks||[]).length?<div className="schedule-table"><div className="schedule-head"><span>任务</span><span>时间</span><span>投递</span><span>下次执行</span><span>状态</span><span/></div>{data.scheduledTasks.map(task=><article key={task.id}><span><b>{task.name}</b><small>{task.skill_name} · {task.creator_name||"飞书用户"}</small></span><span><b>{scheduleText(task)}</b><small>{task.schedule.timezone||"Asia/Shanghai"}</small></span><span><b>{task.delivery_type==="private"?"私聊创建者":"当前群"}</b><small>{task.scope_type==="group"?"群内任务":"个人任务"}</small></span><span><b>{task.next_run_at?time(task.next_run_at):"—"}</b><small>{task.last_error||task.last_run_at&&`上次 ${time(task.last_run_at)}`||"尚未执行"}</small></span><span><em className={`run-status ${task.status}`}>{scheduleStatus(task.status)}</em></span><span className="schedule-actions">{task.status==="active"?<button disabled={busyAction===task.id} onClick={()=>guarded(task.id,{action:"pause_scheduled_task",id:task.id}).catch(()=>{})}>暂停</button>:task.status==="paused"?<button disabled={busyAction===task.id} onClick={()=>guarded(task.id,{action:"resume_scheduled_task",id:task.id}).catch(()=>{})}>恢复</button>:null}<button className="danger" disabled={busyAction===`delete-${task.id}`} onClick={()=>{if(window.confirm(`删除定时任务「${task.name}」？`))guarded(`delete-${task.id}`,{action:"delete_scheduled_task",id:task.id}).catch(()=>{})}}>删除</button></span></article>)}</div>:<div className="control-empty">还没有定时任务。到任意群里 @Alex，说“每天晚上 9 点私聊我项目进度总结”即可创建。</div>}</section>}

      {view==="delegation"&&<section className="ops-card delegation-card"><header><div><p>DELEGATION TRACE</p><h2>主 Agent 与子 Agent 协作</h2></div><span>{(data.delegations||[]).length} 次委派</span></header>{(data.delegations||[]).length?<div className="delegation-list">{(data.delegations||[]).slice(0,12).map(run=><article key={run.id}><div className="delegation-summary"><span><b>{run.skill_name}</b><small>{time(run.created_at)} · 最大并行 {run.max_concurrency}</small></span><em className={`run-status ${run.status}`}>{status(run.status)}</em></div><div className="delegation-flow"><span className="root-agent">ROOT</span>{run.tasks.map(task=><span key={task.id} className={`delegate-task ${task.status}`}><b>{roleLabel(task.role)}</b><small>{formatMs(task.latency_ms)}</small></span>)}</div>{run.error&&<p>{run.error}</p>}</article>)}</div>:<div className="control-empty">复杂周报会在这里展示 Progress、Risk、Todo、Writer 与 Verifier 子 Agent 的父子执行链路。</div>}</section>}

      {view==="memory"&&<section className="memory-layout">
        <section className="ops-card memory-architecture"><header><div><p>HERMES MEMORY</p><h2>会话快照与临时上下文</h2></div><span>按对话框隔离 · 月度刷新</span></header><div className="memory-boundaries"><article><b>Session 临时记忆</b><p>每个群聊或私聊是独立 Session；近期消息自动进入上下文，跨会话回溯由 session_search 完成。</p></article><article><b>USER.md / MEMORY.md</b><p>会话启动时冻结注入，只保存当前用户的偏好、既定事实与长期目标。</p></article><article><b>项目知识完全独立</b><p>项目进展、人物、群消息与飞书文档进入项目知识库，由项目召回工具读取。</p></article></div><div className="session-list">{(data.sessions||[]).length?(data.sessions||[]).map(session=><article key={session.id}><span className="session-kind">{String(session.peer_id).startsWith("group:")?"群":"私"}</span><div><b>{String(session.peer_id).startsWith("group:")?session.external_chat_id||session.peer_id.replace("group:",""):session.peer_id}</b><p>{session.preview||"暂无消息"}</p><small>{session.message_count||0} 条消息 · 更新于 {time(session.updated_at)}</small></div><em>{session.snapshot?session.snapshot.snapshot_period+" 快照":"等待首次快照"}</em></article>):<div className="compact-empty">尚无会话。Alex 收到第一条群聊或私聊消息后，会在这里创建独立 Session。</div>}</div></section>
        <section className="ops-card profile-card"><header><div><p>USER.md</p><h2>稳定用户画像</h2></div><span>{Number(data.profile?.totals?.published||0)} 已发布 · {Number(data.profile?.totals?.candidates||0)} 待确认</span></header><p className="library-intro">这里只保留当前用户跨任务稳定的身份与协作偏好；项目人物、群成员评价与临时行为不进入 USER.md。</p><div className="profile-grid">{data.profile?.entries?.length?data.profile.entries.map(item=><article key={item.id}><div><span className={`memory-status ${item.status}`}>{item.status==="published"?"已发布":item.status==="candidate"?"待确认":"已归档"}</span><small>{item.category} · {Math.round(Number(item.confidence||0)*100)}% · {item.evidence_count} 次证据</small></div><b>{item.key}</b><p>{item.value}</p><footer><span>{item.created_by} · {time(item.created_at)}</span><div>{item.status==="candidate"&&<button className="primary" disabled={busyAction===item.id} onClick={()=>guarded(item.id,{action:"publish_profile",id:item.id}).catch(()=>{})}>确认发布</button>}{item.status!=="archived"&&<button disabled={busyAction===`profile-archive-${item.id}`} onClick={()=>guarded(`profile-archive-${item.id}`,{action:"archive_profile",id:item.id}).catch(()=>{})}>归档</button>}</div></footer></article>):<div className="control-empty">尚无用户画像候选。任务后 Dreaming 默认关闭，明确授权并开启后才会产生候选。</div>}</div></section>
        <section className="ops-card memory-card"><header><div><p>MEMORY.md</p><h2>长期用户记忆</h2></div><button disabled={busyAction==="memory-review"} onClick={()=>guarded("memory-review",{action:"run_memory_review"}).catch(()=>{})}>{busyAction==="memory-review"?"正在审阅…":"立即运行月度审阅"}</button></header><div className="memory-summary"><span><b>{Number(data.memory.totals.published||0)}</b> 已发布</span><span><b>{Number(data.memory.totals.candidates||0)}</b> 待确认</span><p>Memory Curator 只生成候选。原始消息、项目事实与文档保持独立，不会被摘要覆盖。</p></div><div className="memory-list">{data.memory.entries.length?data.memory.entries.map(item=><article key={item.id}><div><span className={`memory-status ${item.status}`}>{item.status==="published"?"长期记忆":item.status==="candidate"?"待确认":"已归档"}</span><small>{memoryType(item.memory_type)} · 置信度 {Math.round(Number(item.confidence||0)*100)}%</small></div><p>{item.content}</p><footer><span>{item.created_by} · {time(item.created_at)}</span><div>{item.status==="candidate"&&<button className="primary" disabled={busyAction===item.id} onClick={()=>guarded(item.id,{action:"publish_memory",id:item.id}).catch(()=>{})}>确认发布</button>}{item.status!=="archived"&&<button disabled={busyAction===`archive-${item.id}`} onClick={()=>guarded(`archive-${item.id}`,{action:"archive_memory",id:item.id}).catch(()=>{})}>归档</button>}</div></footer></article>):<div className="control-empty">尚无长期记忆。你可以对 Bot 说“记住：……”，或运行月度记忆审阅。</div>}</div></section>
        <aside className="ops-card review-card"><header><div><p>MONTHLY REVIEWS</p><h2>月度审阅批次</h2></div><span>{data.memoryCurator?.schedule||"每月"}</span></header>{data.memory.reviews.length?<div className="review-list">{data.memory.reviews.map(review=><article key={review.id}><div><b>{review.status==="candidate_ready"?"候选已生成":review.status==="failed"?"失败":"运行中"}</b><time>{time(review.created_at)}</time></div><small>{review.period_start.slice(0,10)} — {review.period_end.slice(0,10)} · {review.source_count} 条证据</small><p>{review.error||review.summary||"正在压缩本月稳定事实…"}</p></article>)}</div>:<div className="control-empty">首个审阅将在计划时间运行，也可以手动触发。</div>}</aside>
      </section>}

      {view==="knowledge"&&<section className="ops-card knowledge-console"><header><div><p>PROJECT KNOWLEDGE BASE</p><h2>按项目组织的事实与来源</h2></div><span>{data.knowledge?.totals?.projects||0} 个项目 · {data.knowledge?.totals?.items||0} 条知识</span></header><p className="library-intro">项目知识库独立于 Memory。周报会逐个项目调用 project_knowledge_recall，召回需求、进展、Todo、负责人、群聊证据与飞书文档链接。</p><div className="knowledge-projects">{(data.knowledge?.projects||[]).map(project=><details key={project.id}><summary><span><i/><b>{project.name}</b><small>{project.itemCount} 条知识 · {project.documentCount} 份文档 · {project.chatCount} 个群聊</small></span><span>{project.people?.slice(0,4).join("、")||"负责人待确认"}</span></summary><div>{(data.knowledge?.items||[]).filter(item=>item.project_id===project.id).slice(0,20).map(item=><article key={item.id}><span className="knowledge-type">{knowledgeType(item.knowledge_type)}</span><div><b>{item.title}</b><p>{item.content}</p><small>{item.people?.join("、")||"无人物关联"} · {time(item.occurred_at)}</small></div>{item.source_url&&<a href={item.source_url} target="_blank" rel="noreferrer">来源 ↗</a>}</article>)}</div></details>)}</div>{!(data.knowledge?.projects||[]).length&&<div className="control-empty">还没有项目知识。项目进展、关联文档和确认归属的群聊内容会自动进入这里。</div>}</section>}
      {view==="tools"&&<section className="ops-card tool-card"><header><div><p>TOOL AUDIT</p><h2>Agent 工具调用日志</h2></div><span>{data.toolRuns.length} 条</span></header>{data.toolRuns.length?<div className="tool-table"><div className="tool-head"><span>时间</span><span>工具</span><span>Agent 角色</span><span>权限</span><span>耗时</span><span>状态</span></div>{data.toolRuns.map(run=><div key={run.id}><span>{time(run.created_at)}</span><b>{run.tool_name}</b><span>{run.agent_role}</span><code>{run.permission}</code><span>{formatMs(run.latency_ms)}</span><em className={run.status}>{status(run.status)}</em></div>)}</div>:<div className="control-empty">Agent 调用搜索、记忆或写入候选时，会在这里留下可审计记录。</div>}</section>}
    </section>
    {selected&&<TaskRunDrawer run={selected} runs={data.runs} close={()=>setSelected(null)}/>} {selectedSkillId&&<SkillStudio skill={data.skills.find(s=>s.id===selectedSkillId)||null} tags={skillTagCatalog(data.skills)} busy={busyAction} close={()=>setSelectedSkillId(null)} act={guarded}/>} {showAdd&&<AddModel close={()=>setShowAdd(false)} submit={async body=>{await action({action:"create_model",...body});setShowAdd(false)}}/>} {showAddSkill&&<AddSkill close={()=>setShowAddSkill(false)} submit={async body=>{const skill=await action({action:"create_skill",...body}) as Skill;setShowAddSkill(false);setSelectedSkillId(skill.id)}}/>}
    {showAddSkillTag&&<AddSkillTag close={()=>setShowAddSkillTag(false)} submit={async(tagName,tagTone)=>{await action({action:"create_skill_tag",tagName,tagTone});setShowAddSkillTag(false);setSkillTagView(tagName)}}/>}
  </main>
}

function SkillLibraryTable({skills,tag,setTag,manage}:{skills:Skill[];tag:string;setTag:(tag:string)=>void;manage:(id:string)=>void}){
  const catalog=skillTagCatalog(skills),visible=tag==="all"?skills:skills.filter(skill=>skillTagMeta(skill).name===tag);
  return <div className="skill-library-body">
    <aside className="skill-category-section">
      <div className="skill-category-label"><b>用途筛选</b><span>快速定位</span></div>
      <div className="skill-category-summary">
        <button className={tag==="all"?"active all":"all"} onClick={()=>setTag("all")}><i aria-hidden="true">≡</i><b>全部能力</b><strong>{skills.length}</strong></button>
        {catalog.map(item=>{const count=skills.filter(skill=>skillTagMeta(skill).name===item.name).length;return <button key={item.name} className={tag===item.name?`active ${item.tone}`:item.tone} onClick={()=>setTag(item.name)}><i aria-hidden="true">≡</i><b>{item.name}</b><strong>{count}</strong></button>})}
      </div>
    </aside>
    <div className="skill-table"><div className="skill-head"><span>Skill 能力</span><span>生产版本</span><span>调用 / 失败</span><span>待审</span><span>状态</span><span/></div>{visible.map(skill=>{const candidates=skill.versions.filter(version=>version.status==="candidate"||version.status==="draft").length,meta=skillTagMeta(skill);return <button key={skill.id} className={`skill-row tone-${meta.tone}`} onClick={()=>manage(skill.id)}><span className="skill-identity"><span className="skill-copy"><span className="skill-title-line"><b>{skill.name}</b><em className={`skill-use-tag ${meta.tone}`}>{meta.name}</em></span><small>{skill.description}</small></span></span><span>v{skill.version}</span><span>{skill.usage?.calls||0} / {skill.usage?.failures||0}</span><span>{candidates}</span><span className={skill.enabled?"library-status on":"library-status"}>{skill.enabled?"运行中":"已停用"}</span><span className="skill-manage-action">管理 <i>→</i></span></button>})}{!visible.length&&<div className="skill-filter-empty">该用途下还没有已发布 Skill。</div>}</div>
  </div>
}

function skillTagMeta(skill:Skill):SkillTag{
  if(skill.config?.tag?.name)return skill.config.tag;
  const source=`${skill.name} ${skill.description}`.toLowerCase();
  return /report|weekly-report|周报|汇报|简报/.test(source)?defaultSkillTags[1]:/search|document-ingest|docx|wiki|检索|知识/.test(source)?defaultSkillTags[2]:/schedule|timer|定时|自动|提醒/.test(source)?defaultSkillTags[3]:/project|todo|progress|项目|进展|行动项/.test(source)?defaultSkillTags[0]:/memory|dream|画像|记忆/.test(source)?defaultSkillTags[4]:defaultSkillTags[5];
}
function skillTagCatalog(skills:Skill[]){const map=new Map<string,SkillTag>(runtimeSkillTags.map(tag=>[tag.name,tag]));for(const skill of skills){const tag=skillTagMeta(skill);if(!map.has(tag.name))map.set(tag.name,tag)}return[...map.values()]}

function ScopedMemoryMap({scopes,view,setView,openKey,setOpenKey,busy,act}:{scopes?:ControlData["memory"]["scopes"];view:"projects"|"people"|"workspace";setView:(view:"projects"|"people"|"workspace")=>void;openKey:string|null;setOpenKey:(key:string|null)=>void;busy:string;act:(key:string,body:Record<string,unknown>)=>Promise<unknown>}){
  const tabs=([['projects','项目记忆','项目'],['people','人物记忆','人物'],['workspace','通用记忆','通用']] as const),items=scopes?.[view]||[],published=items.reduce((sum,item)=>sum+item.published,0),candidates=items.reduce((sum,item)=>sum+item.candidates,0);
  return <section className="ops-card memory-scope-card">
    <header className="memory-map-header"><div><p>SCOPED MEMORY MAP</p><h2>模型长期记忆地图</h2></div><nav>{tabs.map(([id,label])=><button key={id} className={view===id?"active":""} onClick={()=>setView(id)}>{label}<b>{scopes?.[id]?.length||0}</b></button>)}</nav></header>
    <div className="memory-map-overview"><div><small>当前主体</small><strong>{items.length}</strong><span>{tabs.find(tab=>tab[0]===view)?.[2]}作用域</span></div><div><small>进入生产上下文</small><strong>{published}</strong><span>已发布记忆</span></div><div><small>等待人工判断</small><strong>{candidates}</strong><span>候选记忆</span></div><p><b>长期记忆不是项目流水账。</b>这里只保存跨任务稳定的目标、约束、决策、人物关系和协作偏好；展开主体可以追溯并管理每条底层记忆。</p></div>
    <div className="memory-scope-grid">{items.length?items.map(scope=>{const key=`${scope.type}:${scope.id||scope.name}`,expanded=openKey===key,total=scope.published+scope.candidates,coverage=total?Math.round(scope.published/total*100):0,visibleEntries=scope.entries.filter(entry=>entry.status!=="archived");return <article className={expanded?"memory-scope-item expanded":"memory-scope-item"} key={key}>
      <button className="memory-scope-trigger" onClick={()=>setOpenKey(expanded?null:key)}><span className={`memory-scope-icon ${scope.type}`}>{scope.type==="project"?"项":scope.type==="person"?"人":"全"}</span><span className="memory-scope-title"><small>{scope.type==="project"?"PROJECT MEMORY":scope.type==="person"?"PEOPLE MEMORY":"WORKSPACE MEMORY"}</small><b title={scope.name}>{scope.name}</b><em>{scope.definition}</em></span><span className="memory-scope-counts"><b>{scope.published}<small>已发布</small></b><b className={scope.candidates?"attention":""}>{scope.candidates}<small>待确认</small></b></span><span className="memory-coverage"><i><b style={{width:`${coverage}%`}}/></i><small>{total?`${coverage}% 已确认`:"尚无记忆"}</small></span><span className="memory-chevron">⌄</span></button>
      {expanded&&<div className="memory-scope-detail"><div className="memory-definition"><section><small>主体定义</small><p>{scope.definition}</p></section><section><small>模型当前摘要</small><p>{scope.summary}</p></section></div>{visibleEntries.length?<div className="memory-evidence-list"><header><b>底层记忆</b><span>{visibleEntries.length} 条有效记录</span></header>{visibleEntries.map(entry=><article key={entry.id}><i className={entry.status}/><div><span><b>{memoryType(entry.memory_type)}</b><small>置信度 {Math.round(Number(entry.confidence||0)*100)}% · {time(entry.updated_at)}</small></span><p>{entry.content}</p></div><div className="memory-entry-actions"><em className={`memory-status ${entry.status}`}>{entry.status==="published"?"已发布":"待确认"}</em>{entry.status==="candidate"&&<button className="primary" disabled={busy===entry.id} onClick={()=>act(entry.id,{action:"publish_memory",id:entry.id}).catch(()=>{})}>发布</button>}<button disabled={busy===`archive-${entry.id}`} onClick={()=>act(`archive-${entry.id}`,{action:"archive_memory",id:entry.id}).catch(()=>{})}>归档</button></div></article>)}</div>:<div className="memory-scope-empty"><i>○</i><div><b>尚未形成长期记忆</b><p>该主体目前只有项目事实或消息记录，不会被自动误写进模型长期上下文。</p></div></div>}</div>}
    </article>}):<div className="control-empty">该分类还没有可查看的主体。</div>}</div>
  </section>
}

function SystemPromptStudio({prompt,busy,act}:{prompt:SystemPromptControl;busy:string;act:(key:string,body:Record<string,unknown>)=>Promise<unknown>}){const editable=prompt.versions.find(item=>item.status==="draft")||prompt.active,[content,setContent]=useState(editable?.content||""),[summary,setSummary]=useState("调整角色定位与工作方法");useEffect(()=>{setContent(editable?.content||"")},[editable?.id]);async function save(){await act("prompt-save",{action:"save_system_prompt_draft",content,summary})}return <section className="prompt-console"><section className="ops-card prompt-editor"><header><div><p>SYSTEM PROMPT</p><h2>{prompt.label}</h2></div><span>生产版本 v{prompt.active.version} · 下一轮请求即时生效</span></header><div className="prompt-scope"><b>系统提示词定义 Agent 的稳定身份与边界</b><p>{prompt.description} 具体项目整理、周报、文档读取等执行规则仍由对应 Skill 管理。</p></div><div className="prompt-editor-toolbar"><label>修改说明<input value={summary} onChange={event=>setSummary(event.target.value)} maxLength={300}/></label><div><span>{content.length.toLocaleString("zh-CN")} 字符</span><button className="primary" disabled={busy==="prompt-save"||content.trim().length<300} onClick={save}>{busy==="prompt-save"?"保存中…":"保存为草稿"}</button></div></div><textarea value={content} onChange={event=>setContent(event.target.value)} spellCheck={false}/><footer><span>保存草稿不会影响生产。发布后 Gateway 会把该版本作为真正的 Harness system prompt 发送，历史版本可以随时回滚。</span></footer></section><aside className="ops-card prompt-versions"><header><div><p>VERSION HISTORY</p><h2>版本与发布</h2></div><span>{prompt.versions.length} 个版本</span></header><div>{prompt.versions.map(version=><article key={version.id} className={version.status}><header><span className={`version-status ${version.status}`}>{version.status==="published"?"生产":version.status==="draft"?"草稿":"历史"}</span><b>v{version.version}</b><time>{time(version.updated_at)}</time></header><p>{version.change_summary||"无修改说明"}</p><small>{version.created_by} · {version.content.length.toLocaleString("zh-CN")} 字符</small>{version.status!=="published"&&<footer>{version.status==="draft"&&<button disabled={busy===version.id} onClick={()=>act(version.id,{action:"archive_system_prompt_draft",versionId:version.id})}>归档草稿</button>}<button className="primary" disabled={busy===`publish-${version.id}`} onClick={()=>act(`publish-${version.id}`,{action:"publish_system_prompt_version",versionId:version.id})}>{version.status==="archived"?"回滚到此版本":"发布为生产"}</button></footer>}</article>)}</div></aside></section>}

function SkillStudio({skill,tags,busy,close,act}:{skill:Skill|null;tags:SkillTag[];busy:string;close:()=>void;act:(key:string,body:Record<string,unknown>)=>Promise<unknown>}){const initialTag=skill?skillTagMeta(skill):defaultSkillTags[5],published=skill?.versions.find(v=>v.status==="published"),editable=skill?.versions.find(v=>v.status==="draft"||v.status==="candidate")||published,[content,setContent]=useState(editable?.content||""),[summary,setSummary]=useState("人工优化规则与输出约束"),[tagName,setTagName]=useState(initialTag.name),[tagTone,setTagTone]=useState<SkillTone>(initialTag.tone),[tab,setTab]=useState<"editor"|"versions"|"evolution">("editor");useEffect(()=>{setContent(editable?.content||"")},[editable?.id]);useEffect(()=>{if(skill){const next=skillTagMeta(skill);setTagName(next.name);setTagTone(next.tone)}},[skill?.id,skill?.config?.tag?.name,skill?.config?.tag?.tone]);if(!skill)return null;async function save(){await act("save",{action:"save_skill_draft",skillId:skill!.id,content,summary});setTab("versions")}async function saveTag(){await act("skill-tag",{action:"update_skill_tag",skillId:skill!.id,tagName,tagTone})}async function evolve(){await act("evolve",{action:"evolve_skill",skillId:skill!.id});setTab("versions")}return <div className="control-overlay studio-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><aside className="skill-studio"><header><div><p>SKILL CONTROL</p><h2>{skill.name}</h2><span><em className={`skill-use-tag ${tagTone}`}>{tagName}</em>{published?`生产版本 v${skill.version}`:"尚无生产版本"} · {skill.enabled?"运行中":"已停用"}</span></div><button onClick={close}>×</button></header><section className="skill-tag-editor"><div><small>用途标签</small><input value={tagName} onChange={event=>setTagName(event.target.value)} list="skill-tag-options" maxLength={16}/><datalist id="skill-tag-options">{tags.map(tag=><option key={tag.name} value={tag.name}/>)}</datalist></div><div><small>描边颜色</small><select value={tagTone} onChange={event=>setTagTone(event.target.value as SkillTone)}>{defaultSkillTags.map(tag=><option key={tag.tone} value={tag.tone}>{tag.name}</option>)}</select></div><button className="primary" disabled={busy==="skill-tag"||!tagName.trim()} onClick={saveTag}>{busy==="skill-tag"?"保存中…":"保存标签"}</button></section><nav><button className={tab==="editor"?"active":""} onClick={()=>setTab("editor")}>正文编辑</button><button className={tab==="versions"?"active":""} onClick={()=>setTab("versions")}>版本与发布</button><button className={tab==="evolution"?"active":""} onClick={()=>setTab("evolution")}>自进化记录</button></nav>{tab==="editor"&&<section className="studio-editor"><div className="editor-meta"><label>本次修改说明<input value={summary} onChange={e=>setSummary(e.target.value)}/></label><div><button className="secondary" disabled={Boolean(busy)||!published} onClick={()=>act("toggle-skill",{action:"toggle_capability",id:skill.id,enabled:!skill.enabled})}>{skill.enabled?"停用 Skill":"启用 Skill"}</button><button className="secondary" disabled={busy==="evolve"||!published} onClick={evolve}>{busy==="evolve"?"分析运行日志中…":"交给 Curator 优化"}</button><button className="primary" disabled={busy==="save"} onClick={save}>{busy==="save"?"保存中…":"保存为草稿"}</button></div></div><textarea value={content} onChange={e=>setContent(e.target.value)} spellCheck={false}/><footer><span>编辑不会影响生产；完成评测并审批发布后才会生效。</span><b>{content.length} 字符</b></footer></section>}{tab==="versions"&&<section className="version-list">{skill.versions.map(version=><article key={version.id}><div><span className={`version-status ${version.status}`}>{versionLabel(version.status)}</span><div><h3>v{version.version}</h3><p>{version.change_summary||"无修改说明"}</p></div><time>{time(version.created_at)}</time></div><div className="version-score"><span>创建者：{version.created_by}</span><span>评测：{version.evaluation?.score!=null?`${version.evaluation.score} / 100`:"未评测"}</span></div><pre>{version.content}</pre>{version.status!=="published"&&version.status!=="rejected"&&<footer>{(version.status==="draft"||version.status==="candidate")&&<button className="primary" disabled={busy===version.id} onClick={()=>act(version.id,{action:"publish_skill_draft",versionId:version.id})}>审核并发布</button>}{version.status==="archived"&&<button className="primary" disabled={busy===version.id} onClick={()=>act(version.id,{action:"rollback_skill_version",versionId:version.id})}>回滚到此版本</button>}{version.status!=="archived"&&<button disabled={busy===version.id} onClick={()=>act(version.id,{action:"reject_skill_version",versionId:version.id})}>拒绝</button>}</footer>}</article>)}</section>}{tab==="evolution"&&<section className="evolution-panel"><div className="evolution-policy"><b>权限边界</b><p>Curator 可读取运行日志与生产 Skill，只能写入候选版本；不能发布、发送飞书消息或修改项目数据。</p><button className="primary" disabled={busy==="evolve"||!published} onClick={evolve}>{busy==="evolve"?"生成中…":"基于最新日志生成候选"}</button></div>{skill.evolutions.length?skill.evolutions.map(run=><article key={run.id}><div><b>{run.status==="candidate_ready"?"候选已生成":run.status}</b><time>{time(run.created_at)}</time></div><p>{run.diagnosis||"正在分析 Skill 与运行证据…"}</p></article>):<div className="control-empty">尚无自进化记录。Curator 只会在你主动触发时产生模型调用。</div>}</section>}</aside></div>}

function TaskRunDrawer({run,runs,close}:{run:Run;runs:Run[];close:()=>void}){
  const taskRuns=(run.task_id?runs.filter(item=>item.task_id===run.task_id):[run]).slice().sort((a,b)=>new Date(a.created_at).getTime()-new Date(b.created_at).getTime()),contexts=taskRuns.map(item=>item.context||parseJson<RunContext>(item.context_json,{})),decision=contexts.map(context=>context.routingDecision).find(Boolean) as Record<string,unknown>|undefined,totalTools=taskRuns.flatMap(item=>item.tools||[]);
  return <div className="control-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><aside className="run-drawer structured-run"><header><div><p>AGENT TASK · {run.task_id||run.id}</p><h2>完整模型执行链路</h2></div><button onClick={close}>×</button></header><div className="run-meta"><span>模型调用<b>{taskRuns.length}</b></span><span>工具调用<b>{totalTools.length}</b></span><span>总耗时<b>{formatMs(taskRuns.reduce((sum,item)=>sum+Number(item.latency_ms||0),0))}</b></span><span>状态<b>{taskRuns.some(item=>item.status==="failed")?"存在失败":"完成"}</b></span></div>
    <StructuredSection title="01 · 项目归属与看板写入决策" empty="旧任务没有结构化项目判定记录">{decision&&<><KeyValue label="属于项目" value={decision.belongsToProject?"是":"否"}/><KeyValue label="写入看板" value={decision.shouldWriteBoard?"模型建议写入":"模型判断不写入"}/><KeyValue label="工程门禁" value={decision.allowedWrite?"已放行":"已拦截"}/><KeyValue label="目标项目" value={String(decision.targetProject||"—")}/>{decision.blockedReason&&<KeyValue label="拦截原因" value={String(decision.blockedReason)}/>}<JsonRecord label="用户原文证据" value={decision.evidence||[]}/></>}</StructuredSection>
    <StructuredSection title={`02 · ReAct 全链路 · ${taskRuns.length} 轮模型调用`} empty="没有模型调用记录">{taskRuns.map((item,index)=>{const context=contexts[index],tools=item.tools||[];return <details className="json-record" open key={item.id}><summary>{index+1}. {stageLabel(item.source)} · {status(item.status)} · {formatMs(item.latency_ms)}</summary><LogBlock title="发送给模型的完整 Prompt" value={item.input_text||"无"}/><JsonRecord label="发送给模型的 Context（含记忆、画像、前序工具观察）" value={context}/><LogBlock title="模型原始输出" value={item.output_text||item.error||"没有返回内容"} error={Boolean(item.error)}/>{tools.map(tool=><article className="trace-record" key={tool.id}><header><b>Tool · {tool.tool_name}</b><span>{tool.status} · {tool.permission}</span></header><JsonRecord label="工具输入" value={tool.input||{}}/><JsonRecord label={tool.error?"工具错误":"工具真实返回"} value={tool.error||tool.output}/></article>)}<JsonRecord label="Harness 原始 Trace" value={item.trace||[]}/></details>})}</StructuredSection>
    <details className="raw-run-json"><summary>导出本任务完整 JSON</summary><LogBlock title="Task JSON" value={JSON.stringify(taskRuns,null,2)}/></details></aside></div>;
}
function stageLabel(value:string){return value==="skill-router"?"Skill Router / Plan":value==="root-agent-loop"?"Root Agent / ReAct":value==="project-organize"?"项目结构化提取":value==="weekly-report"?"汇报生成":value}
function RunDrawer({run,close}:{run:Run;close:()=>void}){const context=run.context||parseJson<RunContext>(run.context_json,{}),hermes=context.hermesSession as Record<string,unknown>|undefined,sessionContext=context.sessionContext as Record<string,unknown>|undefined,steps=Array.isArray(context.toolSteps)?context.toolSteps:[],tools=run.tools||[];return <div className="control-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><aside className="run-drawer structured-run"><header><div><p>AGENT RUN · {run.task_id||run.id}</p><h2>{run.model_id||"结构化降级"}</h2></div><button onClick={close}>×</button></header><div className="run-meta"><span>阶段<b>{run.source}</b></span><span>状态<b>{status(run.status)}</b></span><span>耗时<b>{formatMs(run.latency_ms)}</b></span><span>字符<b>{run.input_chars} → {run.output_chars}</b></span></div><LogBlock title="01 · 本轮模型输入" value={run.input_text}/><StructuredSection title="02 · 路由与执行策略" empty="本轮未记录路由策略"><KeyValue label="当前 Skill" value={String(context.selectedSkill||context.mode||"—")}/><KeyValue label="Agent 角色" value={String(context.runtimePolicy?.role||"—")}/><KeyValue label="循环轮次" value={String(context.runtimePolicy?.round||"—")}/><KeyValue label="允许工具" value={Array.isArray(context.runtimePolicy?.allowedTools)?context.runtimePolicy.allowedTools.join("、"):"—"}/></StructuredSection><StructuredSection title="03 · Hermes Session 上下文" empty="本轮不是持久化会话"><JsonRecord label="冻结 USER.md / MEMORY.md 快照" value={hermes||null}/><JsonRecord label="本 Session 近期消息" value={sessionContext||null}/></StructuredSection><StructuredSection title={`04 · ReAct 观察轨迹 · ${steps.length}`} empty="本轮尚未形成前序工具观察">{steps.map((step,index)=><article className="trace-record" key={index}><header><b>Round {step.round||index+1} · {step.call?.name||"tool"}</b><span>{step.error?"失败":"完成"}</span></header><JsonRecord label="工具输入" value={step.call?.input||{}}/><JsonRecord label={step.error?"错误":"工具返回"} value={step.error||step.result}/></article>)}</StructuredSection><StructuredSection title={`05 · 本轮实际工具调用 · ${tools.length}`} empty="该模型轮次没有调用工具">{tools.map(tool=><article className="trace-record" key={tool.id}><header><b>{tool.tool_name}</b><span>{tool.plugin_name||"内置"} · {tool.permission} · {formatMs(tool.latency_ms)}</span></header><JsonRecord label="工具输入" value={tool.input||{}}/><JsonRecord label={tool.error?"错误":"工具返回"} value={tool.error||tool.output}/></article>)}</StructuredSection>{run.error&&<LogBlock title="06 · 运行错误" value={run.error} error/>}<LogBlock title="07 · 模型输出" value={run.output_text||"没有返回内容"}/><details className="raw-run-json"><summary>查看完整原始 JSON</summary><LogBlock title="Context JSON" value={JSON.stringify(context,null,2)}/><LogBlock title="Harness Trace" value={JSON.stringify(run.trace||[],null,2)}/></details></aside></div>}
function StructuredSection({title,empty,children}:{title:string;empty:string;children:React.ReactNode}){const list=Array.isArray(children)?children.filter(Boolean):children;return <section className="structured-section"><h3>{title}</h3>{Array.isArray(list)&&list.length===0?<p className="structured-empty">{empty}</p>:list||<p className="structured-empty">{empty}</p>}</section>}
function KeyValue({label,value}:{label:string;value:string}){return <div className="key-value"><span>{label}</span><b>{value}</b></div>}
function JsonRecord({label,value}:{label:string;value:unknown}){return <details className="json-record" open><summary>{label}</summary><pre>{JSON.stringify(value??null,null,2)}</pre></details>}
function LogBlock({title,value,error=false}:{title:string;value:string;error?:boolean}){return <section className={error?"log-block error":"log-block"}><h3>{title}</h3><pre>{value}</pre></section>}
function AddModel({close,submit}:{close:()=>void;submit:(body:Record<string,unknown>)=>Promise<void>}){const[busy,setBusy]=useState(false),[err,setErr]=useState("");async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const form=new FormData(e.currentTarget);try{await submit(Object.fromEntries(form.entries()))}catch(error){setErr(error instanceof Error?error.message:"保存失败");setBusy(false)}}return <div className="control-overlay"><form className="model-modal" onSubmit={save}><header><div><p>MODEL CONFIG</p><h2>添加请求模型</h2></div><button type="button" onClick={close}>×</button></header><label>显示名称<input name="label" placeholder="例如 DeepSeek V4 Pro" required/></label><label>模型 ID<input name="modelId" placeholder="deepseek-v4-pro" required/></label><div className="form-pair"><label>Temperature<input name="temperature" type="number" step="0.01" defaultValue="0.15"/></label><label>Max tokens<input name="maxTokens" type="number" defaultValue="8192"/></label></div><p className="credential-note">新模型复用当前 API Endpoint 与密钥环境变量；密钥不会进入页面或数据库。</p>{err&&<p className="modal-error">{err}</p>}<footer><button type="button" onClick={close}>取消</button><button className="dark" disabled={busy}>{busy?"保存中…":"保存模型"}</button></footer></form></div>}
function AddSkill({close,submit}:{close:()=>void;submit:(body:Record<string,unknown>)=>Promise<void>}){
  const[busy,setBusy]=useState(false),[err,setErr]=useState(""),[tagName,setTagName]=useState("通用助理"),[tagTone,setTagTone]=useState<SkillTone>("gray"),[creatingTag,setCreatingTag]=useState(false);
  async function save(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);const form=new FormData(e.currentTarget);try{await submit({...Object.fromEntries(form.entries()),tagName,tagTone})}catch(error){setErr(error instanceof Error?error.message:"创建失败");setBusy(false)}}
  function chooseTag(name:string){const next=runtimeSkillTags.find(tag=>tag.name===name);setTagName(name);if(next)setTagTone(next.tone)}
  return <div className="control-overlay"><form className="model-modal skill-create-modal" onSubmit={save}><header><div><p>SKILL CREATION</p><h2>手动创建 Skill</h2></div><button type="button" onClick={close}>×</button></header><label>Skill 名称<input name="name" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" placeholder="例如 meeting-summary" required/></label><label>能力描述<input name="description" minLength={8} maxLength={240} placeholder="说明何时使用以及解决什么问题" required/></label><div className="skill-tag-choice"><label>用途标签<select value={tagName} onChange={event=>chooseTag(event.target.value)}>{runtimeSkillTags.map(tag=><option key={tag.name} value={tag.name}>{tag.name}</option>)}</select></label><button type="button" onClick={()=>setCreatingTag(value=>!value)}>＋ 新建用途</button></div>{creatingTag&&<InlineSkillTagCreator onCreated={(name,tone)=>{setTagName(name);setTagTone(tone);setCreatingTag(false)}}/>}<label>Skill 正文<textarea name="content" minLength={60} defaultValue={"## 目标\n\n说明这个 Skill 要完成的结果。\n\n## 规则\n\n1. 说明输入、执行边界和关键步骤。\n2. 明确不得编造信息或越权写入。\n\n## 验证\n\n说明输出完成前必须检查的条件。"} required/></label><p className="credential-note">先选择最接近的用途；确实没有合适分类时再新建。Skill 创建后进入停用草稿，审核发布后才进入生产能力库。</p>{err&&<p className="modal-error">{err}</p>}<footer><button type="button" onClick={close}>取消</button><button className="dark" disabled={busy}>{busy?"创建中…":"创建草稿"}</button></footer></form></div>
}

function InlineSkillTagCreator({onCreated}:{onCreated:(name:string,tone:SkillTone)=>void}){
  const[name,setName]=useState(""),[tone,setTone]=useState<SkillTone>("gray"),[busy,setBusy]=useState(false),[error,setError]=useState("");
  async function create(){if(!name.trim())return;setBusy(true);setError("");try{const response=await fetch("/api/control",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"create_skill_tag",tagName:name.trim(),tagTone:tone})}),body=await responseJson(response);if(!response.ok)throw new Error(String(body.error||"创建失败"));runtimeSkillTags=[...runtimeSkillTags,body as SkillTag];onCreated(name.trim(),tone)}catch(reason){setError(reason instanceof Error?reason.message:"创建失败")}finally{setBusy(false)}}
  return <div className="inline-tag-creator"><input value={name} onChange={event=>setName(event.target.value)} maxLength={16} placeholder="用途名称，例如会议协作" autoFocus/><select value={tone} onChange={event=>setTone(event.target.value as SkillTone)}>{defaultSkillTags.map(tag=><option key={tag.tone} value={tag.tone}>{tag.name}色</option>)}</select><button type="button" disabled={busy||!name.trim()} onClick={create}>{busy?"创建中…":"创建并选中"}</button>{error&&<small>{error}</small>}</div>
}

function AddSkillTag({close,submit}:{close:()=>void;submit:(name:string,tone:SkillTone)=>Promise<void>}){
  const[name,setName]=useState(""),[tone,setTone]=useState<SkillTone>("gray"),[busy,setBusy]=useState(false),[error,setError]=useState("");
  async function create(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError("");try{await submit(name.trim(),tone)}catch(reason){setError(reason instanceof Error?reason.message:"创建失败");setBusy(false)}}
  return <div className="control-overlay"><form className="model-modal tag-create-modal" onSubmit={create}><header><div><p>SKILL PURPOSE</p><h2>新建用途标签</h2></div><button type="button" onClick={close}>×</button></header><p className="tag-create-guidance">用途用于筛选与分组。名称应描述稳定的能力场景，不要使用具体项目名或临时任务名。</p><label>用途名称<input value={name} onChange={event=>setName(event.target.value)} maxLength={16} placeholder="例如：会议协作" autoFocus required/></label><label>识别颜色<select value={tone} onChange={event=>setTone(event.target.value as SkillTone)}>{defaultSkillTags.map(tag=><option key={tag.tone} value={tag.tone}>{tag.name}色</option>)}</select></label>{error&&<p className="modal-error">{error}</p>}<footer><button type="button" onClick={close}>取消</button><button className="dark" disabled={busy||!name.trim()}>{busy?"创建中…":"创建用途"}</button></footer></form></div>
}
function formatMs(value?:number){if(value==null)return"—";return value<1000?`${Math.round(value)} ms`:`${(value/1000).toFixed(1)} s`}
function formatChars(value:number){return value>999?`${(value/1000).toFixed(1)}k`:String(value||0)}
function time(value:string){return new Date(value).toLocaleString("zh-CN",{month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hour12:false})}
function scheduleText(task:ScheduledTask){const schedule=task.schedule||{type:"daily"},days=["周日","周一","周二","周三","周四","周五","周六"];if(schedule.type==="once")return schedule.runAt?`单次 ${time(schedule.runAt)}`:"单次";if(schedule.type==="weekly")return`${(schedule.weekdays||[]).map(day=>days[day]).join("、")} ${schedule.time||"21:00"}`;return`每天 ${schedule.time||"21:00"}`}
function scheduleStatus(value:string){return value==="active"?"运行中":value==="paused"?"已暂停":value==="running"?"执行中":value==="completed"?"已完成":value==="failed"?"失败":value}
function status(value:string){return value==="completed"?"完成":value==="completed_with_warnings"?"完成·待复核":value==="running"?"运行中":value==="failed"?"失败":value}
function versionLabel(value:string){return value==="published"?"生产":value==="candidate"?"待审批":value==="draft"?"草稿":value==="archived"?"历史":value==="rejected"?"已拒绝":value}
function pretty(value:string){try{return JSON.stringify(JSON.parse(value),null,2)}catch{return value}}
function parseJson<T>(value:string,fallback:T):T{try{return JSON.parse(value) as T}catch{return fallback}}
function architectureLabel(value:string){return({channel_driver:"通信层",harness:"推理运行时",tool_runtime:"工具运行时",delegation:"子 Agent 协调",skill_standard:"Skill 规范",memory_design:"记忆系统"})[value]||value}
function roleLabel(value:string){return({"progress-analyst":"进展分析","risk-analyst":"风险分析","todo-analyst":"Todo 分析","report-writer":"报告写作","report-verifier":"事实校验"})[value]||value}
function memoryType(value:string){return({preference:"偏好",fact:"既定事实",goal:"长期目标"})[value]||value}
function knowledgeType(value:string){return({progress:"进展",document:"文档",group_chat:"群聊",legacy_memory:"历史迁移",fact:"事实"})[value]||value}
